/**
 * Typealias from the type name used in the UDL file to the builtin type.  This
 * is needed because the UDL type name is used in function/method signatures.
 */
public typealias CustomPayload = String

#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public struct FfiConverterTypeCustomPayload: FfiConverter {
    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> CustomPayload {
        return try FfiConverterString.read(from: &buf)
    }

    public static func write(_ value: CustomPayload, into buf: inout [UInt8]) {
        return FfiConverterString.write(value, into: &buf)
    }

    public static func lift(_ value: RustBuffer) throws -> CustomPayload {
        return try FfiConverterString.lift(value)
    }

    public static func lower(_ value: CustomPayload) -> RustBuffer {
        return FfiConverterString.lower(value)
    }
}


